    const hit = h.table[bit & ((1 << FAST) - 1)]!
    if (hit !== 0 && (hit & 15) <= bits) {
      bit >>>= hit & 15
      bits -= hit & 15
      return hit >> 4
    }
    let code = 0
    let first = 0
    let index = 0
    for (let len = 1; len < 16; len += 1) {
      code |= take(1)
      const count = h.counts[len]!
      if (code - first < count) return h.symbols[index + code - first]!
