      cmap.cids ??= new Map()
      for (let k = 0; k + 1 < tokens.length; k += 2) cmap.cids.set(hexNumber(tokens[k]!), Number(tokens[k + 1]))
    } else if (kind === 'cidrange') {
      cmap.cids ??= new Map()
      for (let k = 0; k + 2 < tokens.length; k += 3) {
